document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("stats-grid");n&&(n.innerHTML=IRON_PILLAR_INFO.quickStats.map(n=>`\n                <div class="stat-pill">\n                    <span class="stat-icon">${n.icon}</span>\n                    <span class="stat-value">${n.value}</span>\n                    <span class="stat-label">${n.label}</span>\n                </div>\n            `).join(""));const e=document.getElementById("history-content");e&&(e.innerHTML=`\n            <h3>${HISTORY_TEXT.title}</h3>\n            ${HISTORY_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join("")}\n        `);const t=document.getElementById("composition-list");t&&(t.innerHTML=COMPOSITION.map(n=>`\n                <div class="composition-row">\n                    <span class="composition-label">${n.label}</span>\n                    <span class="composition-value">${n.value}</span>\n                </div>\n            `).join(""));const s=document.getElementById("applications-grid");s&&(s.innerHTML=APPLICATIONS.map(n=>`\n                <div class="principle-card">\n                    <h4>${n.title}</h4>\n                    <p>${n.description}</p>\n                </div>\n            `).join(""));const a=document.getElementById("references-list");a&&(a.innerHTML=REFERENCES.map(n=>`<li><a href="${n.link}" target="_blank" rel="noopener">${n.text}</a></li>`).join(""));const i=document.getElementById("year-slider"),o=document.getElementById("ordinary-rust"),l=document.getElementById("pillar-rust"),r=document.getElementById("ip-readout"),p=[0,35,75,100],c=[0,4,6,8];function d(n){const e=CORROSION_STAGES[n];o&&(o.style.height=`${p[n]}%`),l&&(l.style.height=`${c[n]}%`),r&&(r.innerHTML=`\n                <span class="ip-year">Year ${e.year} — ${e.title}</span>\n                <span class="ip-desc"><strong>Ordinary Iron:</strong> ${e.ordinaryDescription}</span>\n                <span class="ip-desc"><strong>Iron Pillar:</strong> ${e.pillarDescription}</span>\n            `)}i&&(i.addEventListener("input",n=>{d(Number(n.target.value))}),d(0))});